class PreserveOwnerRuntime(StoppedOwnerInstallation):
    """Normal retained restart needs no wire/index installation."""

    def require_selection(self, snapshot: RegistrySnapshot, owners: Sequence[Thread]) -> None:
        pass

    def after_stopped(self, lifecycle: OwnerLifecycle) -> None:
        pass

    def recover(self, stopped: StoppedOwnerBatch) -> tuple[OwnerRestartResult, ...]:
        return stopped.handoff.restore(stopped.lifecycle)

@dataclass(frozen=True)
class PublishOpenhcsRecovery(StoppedOwnerInstallation):
    audience: tuple[OwnerRestartSelection, ...]
    originals: tuple
    original_route: ActiveRoute
    route_directory: int
    current: Path
    receipt: Path
    manifest_bytes: bytes
    candidate: tuple[HistorySource, ...]
    carry_proof: dict

    def failed(self, failure):
        self.leave_stopped(failure)

    def complete(self, stopped):
        self.after_stopped(stopped.lifecycle)
        results = stopped.launch()
        after = stopped.lifecycle.registry.snapshot()
        for previous, result in zip(self.originals, results, strict=True):
            current = after.threads[result.thread]
            if result.thread != previous.name or replace(current, process_identity=previous.process_identity) != previous:
                raise RuntimeError('Original configuration readback differs under retained custody')
            RetainedOwnerLaunch.capture(current, after, interpreter=str(TARGET / 'bin/python'))
        self.note('retained-batch-launched-configurations-verified-public-ui-pending', finished=time.time(), results=FieldCodec.encode(results))
        return results

    @property
    def manifest(self):
        return ROOT / HistoryArchive.filename

    def note(self, phase, **facts):
        previous = json.loads(self.receipt.read_text())
        previous.update(phase=phase, **facts)
        _atomic_write_text(self.receipt, json.dumps(previous, indent=2) + '\n', fsync_parent=True)

    def require_sources(self):
        if self.manifest.read_bytes() != self.manifest_bytes:
            raise RuntimeError('Original history manifest changed; no old-reader inference')
        for source in self.candidate:
            source.validate()
        for proof in self.carry_proof['sources']:
            if any((digest(Path(proof['source']) / name) != expected for name, expected in proof['original_hashes'].items())):
                raise RuntimeError('Original archive changed after carry preparation')

    def require_selection(self, snapshot, owners):
        if {thread.name for thread in owners} != {item.name for item in self.audience}:
            raise RuntimeError('Complete original audience changed; recapture/review required')
        for selection, original in zip(self.audience, self.originals, strict=True):
            current = selection.require_current(snapshot)
            current.require_idle()
            if current != original:
                raise RuntimeError('Original configuration changed')
        self.require_sources()
        InputDispositions(ROOT / InputDispositions.filename).read()
        require_publication_preimages(self.original_route, self.current)
        require_no_clients(self.audience)

    def retain_preimages(self):
        directory = self.receipt.with_suffix('.originals')
        directory.mkdir(mode=448)
        originals = []
        for source in self.candidate:
            archive = Path(source.root)
            destination = directory / archive.name
            destination.mkdir(mode=448)
            for name in ('bus.jsonl', 'registry.json', 'bus_meta.json', 'private_bus_checkpoint.sqlite3', 'private_bus_checkpoint.sqlite3-journal', 'private_bus_checkpoint.sqlite3-wal', 'private_bus_checkpoint.sqlite3-shm'):
                path = archive / name
                if path.exists():
                    originals.append(retain_file(path, destination / name))
            fsync_directory(destination)
        for name in (HistoryArchive.filename, InputDispositions.filename, 'bus_meta.json', 'registry.json', 'coordination.sqlite3', 'coordination.sqlite3-wal', 'coordination.sqlite3-shm'):
            path = ROOT / name
            if path.exists():
                originals.append(retain_file(path, directory / name))
        fsync_directory(directory)
        self.note('original-preimages-retained-before-derived-reset', original_files=originals)

    def protected_originals(self):
        """Read original file observations, never mint or infer input dispositions."""
        paths = {ROOT / 'bus.jsonl'}
        for name in (InputDispositions.filename, 'coordination.sqlite3', 'coordination.sqlite3-wal', 'goal_history.sqlite3', 'goal_waits.json'):
            path = ROOT / name
            if path.exists():
                paths.add(path)
        for original in self.originals:
            if original.session_file is not None:
                session = Path(original.session_file)
                paths.add(session)
                for suffix in ('.input-proof', '.input-proof-journal', '.input-proof-wal', '.input-proof-shm'):
                    proof = Path(str(session) + suffix)
                    if proof.exists():
                        paths.add(proof)
        return {str(path): digest(path) for path in sorted(paths)}

    def after_stopped(self, lifecycle):
        require_publication_preimages(self.original_route, self.current)
        require_no_clients(self.audience)
        snapshot = lifecycle.registry.snapshot()
        for original in self.originals:
            if snapshot.threads[original.name] != original:
                raise RuntimeError('Original settings changed during retirement')
        self.require_sources()
        self.retain_preimages()
        protected = self.protected_originals()
        self.note('all-original-owners-stopped-original-writer-installation')
        for source in self.candidate:
            subprocess.run([str(OLD_WRITER), str(WRITER), source.root, str(TARGET / 'bin/python'), str(INSTALLER), source.wire_root_id], env=clean_environment(), check=True)
            source.validate()
        carried, final_proof = carry(self.manifest)
        if FieldCodec.decode(tuple[HistorySource, ...], carried) != self.candidate:
            raise RuntimeError('Determining provenance changed during index installation')
        if self.manifest.read_bytes() != self.manifest_bytes:
            raise RuntimeError('Manifest CAS preimage changed')
        _atomic_write_text(self.manifest, json.dumps(carried, indent=2) + '\n', fsync_parent=True)
        if self.protected_originals() != protected:
            raise RuntimeError('Protected input/native/wire/goal bytes changed before target launch')
        self.note('original-provenance-published', provenance_carry=final_proof)
        self.note('protected-originals-unchanged-before-target-launch', protected_original_sha256=protected)
        target_route = replace(self.original_route, native_package=NATIVE)
        _publish_active_route_locked(target_route, active_route_path(), self.route_directory, expected=self.original_route)
        for command in COMMANDS:
            link = LINKS / command
            if link.readlink() != self.current / 'bin' / command:
                raise RuntimeError('Default changed during publication; remain stopped')
            temporary = LINKS / (command + '.openhcs-recovery-publish')
            temporary.symlink_to(TARGET / 'bin' / command)
            temporary.replace(link)
        descriptor = os.open(LINKS, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        if read_active_route() != target_route:
            raise RuntimeError('Target route readback differs')
        self.note('target-route-and-defaults-published-before-retained-launch')

@dataclass(frozen=True)
class PublishRetainedSummary(StoppedOwnerInstallation):
    cohort: ReviewedRetainedSummaryCohort
    audience: tuple[OwnerRestartSelection, ...]
    originals: tuple[Thread, ...]
    task_carry: StoppedOwnerInstallation
    runtime_installation: RuntimeInstallation
    route_directory: int
    receipt: Path
    recovery_originals: tuple[ReviewedArtifact, ...] = field(init=False, repr=False)

    def __post_init__(self):
        object.__setattr__(self, 'recovery_originals', tuple((ReviewedArtifact(path, digest(path)) for path in sorted(self.recovery_paths()))))

    def recovery_paths(self) -> frozenset[Path]:
        """Include payloads the installation may replace, not only invariants."""
        from agent_comms.wire_log import WireLog
        bus = WireLog(ROOT / 'bus.jsonl')
        paths = self.protected_files().union(RuntimeCompactionFiles(ROOT).paths, RuntimeNativeFiles(ROOT).paths, (bus.path, bus.metadata_path))
        return frozenset((path for path in paths if path.exists() or path.is_symlink()))

    def require_recovery_originals(self):
        if self.recovery_paths() != frozenset((item.path for item in self.recovery_originals)):
            raise RuntimeError('Original recovery membership changed; remain stopped')
        for original in self.recovery_originals:
            original.require_original()

    def note(self, phase, **facts):
        previous = json.loads(self.receipt.read_text())
        previous.update(phase=phase, **facts)
        _atomic_write_text(self.receipt, json.dumps(previous, indent=2) + '\n', fsync_parent=True)

    def require_selection(self, snapshot, owners):
        live = {thread.name for thread in snapshot.threads.values() if thread.role.executable and snapshot.statuses[thread.name].active and thread.process_alive}
        if live != {thread.name for thread in owners} or live != {item.name for item in self.audience}:
            raise RuntimeError('Complete original owner audience changed; recapture/review required')
        for selection, original in zip(self.audience, self.originals, strict=True):
            current = selection.require_current(snapshot)
            current.require_idle()
            if current != original:
                raise RuntimeError('Original owner settings changed')
        self.cohort.require_original()
        require_no_clients(self.audience)
        InputDispositions(ROOT / InputDispositions.filename).read()
        self.task_carry.require_selection(snapshot, owners)

    def protected_files(self) -> frozenset[Path]:
        paths = set()
        for name in (InputDispositions.filename, 'coordination.sqlite3', 'native_prompt_bindings.sqlite3', 'goal_history.sqlite3', 'goal_waits.json', 'goal_pause_events.json'):
            for suffix in ('', '-journal', '-wal', '-shm'):
                path = ROOT / (name + suffix)
                if path.exists() or path.is_symlink():
                    paths.add(path)
        for original in self.originals:
            if original.session_file is not None:
                session = Path(original.session_file)
                paths.add(session)
                for suffix in ('.input-proof', '.input-proof-journal', '.input-proof-wal', '.input-proof-shm'):
                    proof = Path(str(session) + suffix)
                    if proof.exists() or proof.is_symlink():
                        paths.add(proof)
        paths.update((path for path in RuntimeGoalFiles(ROOT).paths if path.exists() or path.is_symlink()))
        return frozenset(paths)

    def after_stopped(self, lifecycle):
        self.cohort.require_original()
        require_no_clients(self.audience)
        snapshot = lifecycle.registry.snapshot()
        for original in self.originals:
            if original.process_alive or snapshot.threads[original.name] != original:
                raise RuntimeError('Original owner exit/configuration proof changed')
        directory = self.receipt.with_suffix('.originals')
        directory.mkdir(mode=448)
        PrivateDirectoryRole.require(directory.lstat())
        paths = self.protected_files()
        protected = {str(path): digest(path) for path in sorted(paths)}
        with ExitStack() as custody:
            runtime = custody.enter_context(RuntimeCompactionFiles(ROOT).acquire())
            goals = custody.enter_context(RuntimeGoalFiles(ROOT).acquire())
            unchanged = self.runtime_installation.unchanged_protected(paths, runtime).difference(goals.paths)
            invariant = {str(path): protected[str(path)] for path in unchanged}
            original_files = self.runtime_installation.retain_protected(paths, directory)
            retain_file(ROOT / 'registry.json', directory / 'registry.json')
            fsync_directory(directory)
            fsync_directory(directory.parent)
            self.note('all-original-owners-stopped-originals-audited', protected_original_sha256=protected, protected_preimages=original_files, registry_original_sha256=digest(directory / 'registry.json'))
            goal_installation = self.runtime_installation.synchronize_goal(goals, directory / 'goal-ledger')
            installed_goals = custody.enter_context(RuntimeGoalFiles(ROOT).acquire())
            self.task_carry.after_stopped(lifecycle)
            installed = self.runtime_installation.install(runtime, directory / 'runtime-compaction')
            if self.protected_files() != paths or {str(path): digest(path) for path in unchanged} != invariant:
                raise RuntimeError('Original input/native/proof/goal bytes changed; remain stopped')
            installed_goals.require_original()
            self.note('runtime-installed-protected-originals-unchanged', runtime_installation=installed, goal_installation=goal_installation, byte_invariant_originals=invariant)
        self.cohort.publish(self.route_directory)
        self.note('target-route-and-defaults-published-before-retained-launch')

    def failed(self, failure):
        self.restore_unchanged(failure)

    def recover(self, stopped):
        """Only byte-identical originals may return to their original runtime.

        These physical proofs precede ANY original registry decoder. A committed
        #514 ledger or changed route therefore cannot be read/reverted by #508.
        The same RAM handoff and original wire OFD cross the existing child.
        """
        self.cohort.require_publication_originals()
        self.require_recovery_originals()
        snapshot = stopped.lifecycle.registry.snapshot()
        for original in self.originals:
            if snapshot.threads[original.name] != original:
                raise RuntimeError('Original stopped configuration changed; remain stopped')
        restored = restore_stopped_batch(stopped)
        self.note('failed-install-original-runtime-restored', restored=FieldCodec.encode(restored), finished=time.time())
        return restored

    def complete(self, stopped):
        self.after_stopped(stopped.lifecycle)
        results = stopped.launch()
        snapshot = stopped.lifecycle.registry.snapshot()
        for original, result in zip(self.originals, results, strict=True):
            current = snapshot.threads[result.thread]
            if result.thread != original.name or replace(current, process_identity=original.process_identity) != original:
                raise RuntimeError('Original settings readback differs under retained wire custody')
            RetainedOwnerLaunch.capture(current, snapshot, interpreter=str(self.cohort.target / 'bin/python'))
        self.note('retained-batch-launched-configurations-verified-public-ui-pending', results=FieldCodec.encode(results), finished=time.time())
        return results

def recovery_paths(self) -> frozenset[Path]:
    """Include payloads the installation may replace, not only invariants."""
    from agent_comms.wire_log import WireLog
    bus = WireLog(ROOT / 'bus.jsonl')
    paths = self.protected_files().union(RuntimeCompactionFiles(ROOT).paths, RuntimeNativeFiles(ROOT).paths, (bus.path, bus.metadata_path))
    return frozenset((path for path in paths if path.exists() or path.is_symlink()))

def require_recovery_originals(self):
    if self.recovery_paths() != frozenset((item.path for item in self.recovery_originals)):
        raise RuntimeError('Original recovery membership changed; remain stopped')
    for original in self.recovery_originals:
        original.require_original()

@dataclass(frozen=True)
class RetainedIndexCutover(StoppedOwnerInstallation):
    original_python: Path
    wire_root_id: str
    native_package: Path
    writer_script: ClassVar[str] = 'retained_index_writer.py'
    installer_script: ClassVar[str] = 'install_retained_index.py'

    def failed(self, failure):
        self.leave_stopped(failure)

    @property
    def operation_arguments(self) -> tuple[str, ...]:
        return ()

    def require_selection(self, snapshot, owners) -> None:
        audience = {thread.name for thread in snapshot.threads.values() if thread.role.executable and snapshot.statuses[thread.name].active and thread.process_alive}
        if {thread.name for thread in owners} != audience:
            raise RelationViolationError('Index cutover requires every live executable owner.')
        if not self.original_python.is_absolute() or not self.original_python.is_file():
            raise RelationViolationError('Original installed writer interpreter is required.')
        WireRootIdText.from_text(self.wire_root_id)
        verify_native_package(self.native_package)
        environment = dict(os.environ)
        environment.pop('PYTHONPATH', None)
        original_schema = subprocess.run([str(self.original_python), str(Path(__file__).with_name('checkpoint_schema.py'))], env=environment, check=True, capture_output=True, text=True).stdout.strip()
        if original_schema == declared_schema_digest():
            raise RelationViolationError('Installed schemas already match; retained reset is unnecessary.')

    def after_stopped(self, lifecycle) -> None:
        environment = dict(os.environ)
        environment.pop('PYTHONPATH', None)
        subprocess.run([str(self.original_python), str(Path(__file__).with_name(self.writer_script)), str(lifecycle.root), sys.executable, str(Path(__file__).with_name(self.installer_script)), self.wire_root_id, *self.operation_arguments], env=environment, check=True)
        lifecycle.pin_private_nk_launch(lifecycle.root, self.wire_root_id, self.native_package)

@dataclass(frozen=True)
class RetainedTaskSourceCarry(StoppedOwnerInstallation):
    original_python: Path
    wire_root: Path
    wire_root_id: str
    receipt: Path

    def failed(self, failure):
        self.leave_stopped(failure)

    def require_selection(self, snapshot, owners):
        live = {thread.incarnation for thread in snapshot.threads.values() if thread.role.executable and thread.process_alive}
        if live != {thread.incarnation for thread in owners}:
            raise RelationViolationError('Task carry requires the whole live owner audience.')
        if not self.original_python.is_absolute() or not self.original_python.is_file():
            raise RelationViolationError('Original installed decoder is required.')
        if not self.receipt.is_absolute() or self.receipt.exists() or self.receipt.is_symlink():
            raise RelationViolationError('Task carry receipt must be fresh persistent storage.')
        parent = self.receipt.parent.stat()
        if self.receipt.parent.is_symlink() or parent.st_uid != os.geteuid() or parent.st_mode & 18:
            raise RelationViolationError('Task carry receipt parent is not owner-controlled.')
        originals = self.receipt.with_name(self.receipt.name + '.originals')
        if originals.exists() or originals.is_symlink():
            raise RelationViolationError('Existing preimages prohibit another carry attempt.')
        environment = dict(os.environ)
        environment.pop('PYTHONPATH', None)
        subprocess.run([self.original_python, Path(__file__).with_name('read_original_task_preimage.py'), self.wire_root, self.wire_root_id], env=environment, stdout=subprocess.DEVNULL, check=True)

    def after_stopped(self, lifecycle):
        if lifecycle.root.resolve(strict=True) != self.wire_root.resolve(strict=True):
            raise RelationViolationError('Stopped task carry belongs to another root.')
        environment = dict(os.environ)
        environment.pop('PYTHONPATH', None)
        subprocess.run([str(self.original_python), str(Path(__file__).with_name('retained_task_writer.py')), str(lifecycle.root), sys.executable, str(Path(__file__).with_name('install_retained_task_source.py')), self.wire_root_id, str(self.receipt)], env=environment, check=True)

@dataclass(frozen=True)
class ActivateGlobalExtension(StoppedOwnerInstallation):
    sources: tuple[GlobalSourceInstall, ...]
    preimages: Path

    def require_selection(self, snapshot, owners):
        if self.preimages.exists() or self.preimages.is_symlink():
            raise RuntimeError('Original source activation attempt requires review')
        for source in self.sources:
            source.require_original()

    def after_stopped(self, lifecycle):
        self.require_selection(lifecycle.registry.snapshot(), ())
        self.preimages.mkdir(mode=448)
        for source in self.sources:
            source.retain_original(self.preimages)
        fsync_directory(self.preimages)
        fsync_directory(self.preimages.parent)
        for source in self.sources:
            source.install()

