class PublishRetainedSummary(StoppedOwnerInstallation):
    cohort: ReviewedRetainedSummaryCohort
    audience: tuple[OwnerRestartSelection, ...]
    originals: tuple[Thread, ...]
    task_carry: StoppedOwnerInstallation
    runtime_installation: RuntimeInstallation
    route_directory: int
    receipt: Path

    def note(self, phase, **facts):
        previous = json.loads(self.receipt.read_text())
        previous.update(phase=phase, **facts)
        _atomic_write_text(self.receipt, json.dumps(previous, indent=2) + '\n', fsync_parent=True)

    def require_selection(self, snapshot, owners):
        live = {thread.name for thread in snapshot.threads.values() if thread.role.executable and snapshot.statuses[thread.name].active and thread.process_alive}
        if live != {thread.name for thread in owners} or live != {item.name for item in self.audience}:
            raise RuntimeError('Complete original owner audience changed; recapture/review required')
        for selection, original in zip(self.audience, self.originals, strict=True):
            current = selection.require_current(snapshot)
            current.require_idle()
            if current != original:
                raise RuntimeError('Original owner settings changed')
        self.cohort.require_original()
        require_no_clients(self.audience)
        InputDispositions(ROOT / InputDispositions.filename).read()
        self.task_carry.require_selection(snapshot, owners)

    def protected_files(self):
        paths = set()
        for name in (InputDispositions.filename, 'coordination.sqlite3', 'native_prompt_bindings.sqlite3', 'goal_history.sqlite3', 'goal_waits.json', 'goal_pause_events.json'):
            for suffix in ('', '-journal', '-wal', '-shm'):
                path = ROOT / (name + suffix)
                if path.exists() or path.is_symlink():
                    paths.add(path)
        for original in self.originals:
            if original.session_file is not None:
                session = Path(original.session_file)
                paths.add(session)
                for suffix in ('.input-proof', '.input-proof-journal', '.input-proof-wal', '.input-proof-shm'):
                    proof = Path(str(session) + suffix)
                    if proof.exists() or proof.is_symlink():
                        paths.add(proof)
        return paths

    def after_stopped(self, lifecycle):
        self.cohort.require_original()
        require_no_clients(self.audience)
        snapshot = lifecycle.registry.snapshot()
        for original in self.originals:
            if original.process_alive or snapshot.threads[original.name] != original:
                raise RuntimeError('Original owner exit/configuration proof changed')
        directory = self.receipt.with_suffix('.originals')
        directory.mkdir(mode=448)
        PrivateDirectoryRole.require(directory.lstat())
        paths = self.protected_files()
        protected = {str(path): digest(path) for path in sorted(paths)}
        unchanged = self.runtime_installation.unchanged_protected(paths)
        invariant = {str(path): protected[str(path)] for path in unchanged}
        with RuntimeCompactionFiles(ROOT).acquire() as runtime:
            original_files = self.runtime_installation.retain_protected(paths, directory)
            retain_file(ROOT / 'registry.json', directory / 'registry.json')
            fsync_directory(directory)
            fsync_directory(directory.parent)
            self.note('all-original-owners-stopped-originals-audited', protected_original_sha256=protected, protected_preimages=original_files)
            self.task_carry.after_stopped(lifecycle)
            installed = self.runtime_installation.install(runtime, directory / 'runtime-compaction')
            if self.protected_files() != paths or {str(path): digest(path) for path in unchanged} != invariant:
                raise RuntimeError('Original input/native/proof/goal bytes changed; remain stopped')
            self.note('runtime-installed-protected-originals-unchanged', runtime_installation=installed, byte_invariant_originals=invariant)
        self.cohort.publish(self.route_directory)
        self.note('target-route-and-defaults-published-before-retained-launch')

    def complete(self, stopped):
        self.after_stopped(stopped.lifecycle)
        results = stopped.launch()
        snapshot = stopped.lifecycle.registry.snapshot()
        for original, result in zip(self.originals, results, strict=True):
            current = snapshot.threads[result.thread]
            if result.thread != original.name or replace(current, process_identity=original.process_identity) != original:
                raise RuntimeError('Original settings readback differs under retained wire custody')
            RetainedOwnerLaunch.capture(current, snapshot, interpreter=str(self.cohort.target / 'bin/python'))
        self.note('retained-batch-launched-configurations-verified-public-ui-pending', results=FieldCodec.encode(results), finished=time.time())
        return results

@dataclass(frozen=True)
class RetainedIndexCutover(StoppedOwnerInstallation):
    original_python: Path
    wire_root_id: str
    native_package: Path
    writer_script: ClassVar[str] = 'retained_index_writer.py'
    installer_script: ClassVar[str] = 'install_retained_index.py'

    @property
    def operation_arguments(self) -> tuple[str, ...]:
        return ()

    def require_selection(self, snapshot, owners) -> None:
        audience = {thread.name for thread in snapshot.threads.values() if thread.role.executable and snapshot.statuses[thread.name].active and thread.process_alive}
        if {thread.name for thread in owners} != audience:
            raise RelationViolationError('Index cutover requires every live executable owner.')
        if not self.original_python.is_absolute() or not self.original_python.is_file():
            raise RelationViolationError('Original installed writer interpreter is required.')
        WireRootIdText.from_text(self.wire_root_id)
        verify_native_package(self.native_package)
        environment = dict(os.environ)
        environment.pop('PYTHONPATH', None)
        original_schema = subprocess.run([str(self.original_python), str(Path(__file__).with_name('checkpoint_schema.py'))], env=environment, check=True, capture_output=True, text=True).stdout.strip()
        if original_schema == declared_schema_digest():
            raise RelationViolationError('Installed schemas already match; retained reset is unnecessary.')

    def after_stopped(self, lifecycle) -> None:
        environment = dict(os.environ)
        environment.pop('PYTHONPATH', None)
        subprocess.run([str(self.original_python), str(Path(__file__).with_name(self.writer_script)), str(lifecycle.root), sys.executable, str(Path(__file__).with_name(self.installer_script)), self.wire_root_id, *self.operation_arguments], env=environment, check=True)
        lifecycle.pin_private_nk_launch(lifecycle.root, self.wire_root_id, self.native_package)

@dataclass(frozen=True)
class RetainedTaskSourceCarry(StoppedOwnerInstallation):
    original_python: Path
    wire_root: Path
    wire_root_id: str
    receipt: Path

    def require_selection(self, snapshot, owners):
        live = {thread.incarnation for thread in snapshot.threads.values() if thread.role.executable and thread.process_alive}
        if live != {thread.incarnation for thread in owners}:
            raise RelationViolationError('Task carry requires the whole live owner audience.')
        if not self.original_python.is_absolute() or not self.original_python.is_file():
            raise RelationViolationError('Original installed decoder is required.')
        if not self.receipt.is_absolute() or self.receipt.exists() or self.receipt.is_symlink():
            raise RelationViolationError('Task carry receipt must be fresh persistent storage.')
        parent = self.receipt.parent.stat()
        if self.receipt.parent.is_symlink() or parent.st_uid != os.geteuid() or parent.st_mode & 18:
            raise RelationViolationError('Task carry receipt parent is not owner-controlled.')
        originals = self.receipt.with_name(self.receipt.name + '.originals')
        if originals.exists() or originals.is_symlink():
            raise RelationViolationError('Existing preimages prohibit another carry attempt.')
        environment = dict(os.environ)
        environment.pop('PYTHONPATH', None)
        subprocess.run([self.original_python, Path(__file__).with_name('read_original_task_preimage.py'), self.wire_root, self.wire_root_id], env=environment, stdout=subprocess.DEVNULL, check=True)

    def after_stopped(self, lifecycle):
        if lifecycle.root.resolve(strict=True) != self.wire_root.resolve(strict=True):
            raise RelationViolationError('Stopped task carry belongs to another root.')
        environment = dict(os.environ)
        environment.pop('PYTHONPATH', None)
        subprocess.run([str(self.original_python), str(Path(__file__).with_name('retained_task_writer.py')), str(lifecycle.root), sys.executable, str(Path(__file__).with_name('install_retained_task_source.py')), self.wire_root_id, str(self.receipt)], env=environment, check=True)
